# With Functions
def get_name():
    return input("Enter your name: ")
def get_score():
    return int(input("Enter a score: "))
def calculate_average(score1, score2):
    return (score1 + score2) / 2
def display_result(name, average):
    print(f"{name}'s average is {average}.")
name = get_name()
score1 = get_score()
score2 = get_score()
average = calculate_average(score1, score2)
display_result(name, average)

# One Function, One Task
def get_price():
    return float(input("Enter the item price: "))
def calculate_tax(price):
    return price * 0.05
def calculate_total(price, tax):
    return price + tax
def display_total(total):
    print(f"Total: ${total:.2f}")
price = get_price()
tax = calculate_tax(price)
total = calculate_total(price, tax)
display_total(total)

